#include <map>
#include <string>

void safe_erase(std::map<int, std::string>& coll, const std::string& value) {
    auto pos = coll.begin();
    while (pos != coll.end()) {
        if (pos->second == value) {
            // pos++ yields the old iterator for erase,
            // while advancing pos to the next valid element.
            coll.erase(pos++); // Pre-C++11/17 safe pattern
        } 
        else {
            ++pos;
        }
    }
}
